import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`construction-estimator`,heroTitle:`Go from scope to estimate in minutes`,heroSubtitle:`Perplexity Computer scopes your job, prices materials and labor at local rates, and drafts a client-ready bid — automatically.`,heroCta:`Get started`,hasInputUrl:!1,heroOverlaySteps:[`Scoping the job and flagging assumptions`,`Researching material costs and local labor rates`,`Building the phase-by-phase estimate with line items`,`Priced bid and client-ready proposal — ready to send`],generatingSteps:[`Analyzing your job scope and requirements`,`Designing an agent to scope, price, and draft your bid`,`Configuring material cost research for your region`,`Setting up your estimate spreadsheet and proposal`],featureSectionTitle:`From job scope to client-ready bid`,featureCardTitles:[`Connects to your bidding stack`,`Outputs you can send`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Docs, Gmail, Google Drive — Computer builds your estimate where you already work and sends the proposal from your inbox.`,`Line-item estimates. Material quantity takeoffs. Labor pricing by trade. A client-ready proposal, priced and formatted.`],capabilitySectionTitle:`Your construction estimator, on autopilot`,capabilitySectionSubtitle:`Describe the job, step away, come back to a priced bid and proposal.`,capabilityCards:[{title:`Scope Of Work`,description:`Computer can turn a plain-language job description into a full scope of work — with assumptions flagged for your review.`},{title:`Material & Labor Pricing`,description:`Computer can price lumber, concrete, and fixtures at current regional rates — and labor by trade.`},{title:`Line-Item Estimates`,description:`Computer can break the job into phases with line-item costs, quantities, and contingency built in.`},{title:`Connect Your Tools`,description:`Computer can build the estimate in Google Sheets, the proposal in Google Docs, and send it through Gmail.`},{title:`Remember & Learn`,description:`Computer can remember your rates, markups, and past jobs — so every new estimate starts from how you actually price.`},{title:`Monitor & Alert`,description:`Computer can watch material prices for your open bids and alert you when costs move before the job is locked.`}]});export{t as default};
